// Simple response to any message
const message = $input.first().json.message;
const chatId = message.chat.id;
const messageId = message.message_id;

let responseText = '';
let messageType = '';

if (message.voice) {
  messageType = 'voice note';
  responseText = `🎤 **Voice Note Received!**

✅ Duration: ${message.voice.duration} seconds
📊 File size: ${Math.round(message.voice.file_size/1024)}KB

🤖 **I understand you sent a voice message!**

Here's what I would do:
1. 🎯 Transcribe your audio
2. 🧠 Analyze content with AI
3. 📋 Extract actionable tasks
4. 🚀 Route to GitHub/Notion/Claude

_Full AI processing coming soon!_`;
} else if (message.text) {
  messageType = 'text message';
  const text = message.text;
  responseText = `💬 **Text Message Received!**

✅ **Your message:** "${text.substring(0, 100)}${text.length > 100 ? '...' : ''}"

🤖 **I understand your request!**

Here's what I would do:
1. 🧠 Analyze your message
2. 📋 Extract tasks and bugs
3. 🎯 Categorize by priority
4. 🚀 Route to appropriate systems

_Full AI processing coming soon!_`;
} else {
  return null; // Skip other message types
}

return {
  chatId: chatId,
  messageId: messageId,
  responseText: responseText,
  messageType: messageType
};
